    expect(s).toContain("walk dog");
  });
  it("renders incomplete todos with [ ]", () => {
    const s = formatTodo({ id: 1, title: "buy milk", completed: false });
    expect(s.startsWith("[ ]")).toBe(true);
    expect(s).toContain("buy milk");
  });
