    const s = formatList([
      { id: 1, title: "buy milk", completed: false },
      { id: 2, title: "walk dog", completed: true },
    ]);
    expect(s).toContain("[ ] buy milk");
    expect(s).toContain("[x] walk dog");
  });
});
